import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            S = next(iterator)
        except StopIteration:
            break

        n = len(S)
        doubled = S + S
        count = 0

        for k in range(n):
            substring = doubled[k:k+n]
            if substring == substring[::-1]:
                count += 1

        results.append(str(count))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
